using System;
using UnityEngine;

namespace MoonProject.Gameplay
{
    /// <summary>
    /// The materials and Art prefabs gameplay effects draw with, generated by the Gameplay/Materials and
    /// Gameplay/FeelVfx builders (Generated/Gameplay). Runtime code only reads it.
    /// </summary>
    public sealed class GameplayVisuals : ScriptableObject
    {
        [Tooltip("Pickup flash where salvage folds into 07 (TechGlow, additive, fresnel ball).")]
        [SerializeField] private Material _flash;

        [Tooltip("A salvage piece's halo shell (TechGlow, additive, inverted hull with fresnel).")]
        [SerializeField] private Material _pieceHalo;

        [Tooltip("Camera-facing glints over pieces held on their wrecks (Glint shader, WarmLamp amber).")]
        [SerializeField] private Material _partGlint;

        [Tooltip("The feel kit's glowing sprites: charge motes, the glow bead, flashes, vacuum sparks and slag beads " +
                 "(SoftGlow, white, additive, soft round; each sprite carries its own colour).")]
        [SerializeField] private Material _feelSprite;

        [Tooltip("The cutting beam's hot white core (SoftGlow, additive, soft across).")]
        [SerializeField] private Material _beamCore;

        [Tooltip("The cutting beam's cyan sheath round the core (SoftGlow, additive, soft across, faint bands).")]
        [SerializeField] private Material _beamSheath;

        [Tooltip("The molten seam on a piece, emission by heat (HeatSeam shader).")]
        [SerializeField] private Material _heatSeam;

        [Tooltip("Every look number of the feel kit (Data/Tuning/Gameplay/FeelVfxTuning.asset).")]
        [SerializeField] private FeelVfxTuning _feelTuning;

        [Tooltip("Art's R1 crates (Generated/Art/R1/Models/Crates: Crate_S, Crate_M, Crate_L), each named as its " +
                 "prefab: the opening's supply crates (opening-v2 §4).")]
        [SerializeField] private GameObject[] _containers = Array.Empty<GameObject>();

        [Tooltip("Valid placement / un-welded stage hologram material (Generated/Art/Palette/M_Hologram.mat).")]
        [SerializeField] private Material _hologramValid;

        [Tooltip("Invalid placement hologram material (Generated/Art/Palette/M_HologramInvalid.mat).")]
        [SerializeField] private Material _hologramInvalid;

        public Material Flash => _flash;
        public Material PieceHalo => _pieceHalo;
        public Material PartGlint => _partGlint;
        public Material FeelSprite => _feelSprite;
        public Material BeamCore => _beamCore;
        public Material BeamSheath => _beamSheath;
        public Material HeatSeam => _heatSeam;
        public FeelVfxTuning FeelTuning => _feelTuning;
        public Material HologramValid => _hologramValid;
        public Material HologramInvalid => _hologramInvalid;

        /// <summary>Art's crate named <paramref name="name"/> (its prefab name), or null.</summary>
        public GameObject Container(string name)
        {
            for (int i = 0; i < _containers.Length; i++)
            {
                if (_containers[i] != null && _containers[i].name == name)
                {
                    return _containers[i];
                }
            }

            return null;
        }

        /// <summary>Null when every material and prefab is assigned, else the first missing one.</summary>
        public string Validate()
        {
            return _flash == null ? "flash material is missing"
                : _pieceHalo == null ? "piece halo material is missing"
                : _partGlint == null ? "part glint material is missing"
                : _containers == null || _containers.Length == 0 || Array.IndexOf(_containers, null) >= 0
                    ? "Art's crates are missing (run Gameplay/Materials)"
                : _feelSprite == null ? "feel sprite material is missing (run Gameplay/FeelVfx)"
                : _beamCore == null ? "beam core material is missing (run Gameplay/FeelVfx)"
                : _beamSheath == null ? "beam sheath material is missing (run Gameplay/FeelVfx)"
                : _heatSeam == null ? "heat seam material is missing (run Gameplay/FeelVfx)"
                : _feelTuning == null ? "the feel VFX tuning is missing (run Gameplay/FeelVfx)"
                : _hologramValid == null ? "hologram valid material is missing (run Gameplay/Materials)"
                : _hologramInvalid == null ? "hologram invalid material is missing (run Gameplay/Materials)"
                : null;
        }

        /// <summary>
        /// The cut feel kit's materials, written by Gameplay/FeelVfx (its own editor assembly) after Gameplay/Materials.
        /// </summary>
        public void PopulateFeel(Material feelSprite, Material beamCore, Material beamSheath, Material heatSeam,
            FeelVfxTuning tuning)
        {
            _feelTuning = tuning;
            _feelSprite = feelSprite;
            _beamCore = beamCore;
            _beamSheath = beamSheath;
            _heatSeam = heatSeam;
        }

        internal void PopulateContainers(GameObject[] containers)
        {
            _containers = containers ?? throw new ArgumentNullException(nameof(containers));
        }

        internal void PopulateHologram(Material valid, Material invalid)
        {
            _hologramValid = valid;
            _hologramInvalid = invalid;
        }

        internal void Populate(Material flash, Material pieceHalo, Material partGlint)
        {
            _flash = flash;
            _pieceHalo = pieceHalo;
            _partGlint = partGlint;
        }
    }
}
